  return (usr, msg, next) => {
    const now = +new Date();

    const lastMessage = usr._last_message_date;

    usr._last_message_date = now;

    if (!lastMessage) {
      return next();
    }

    if (now - lastMessage > delayMS) {
      return next();
    }

    if (typeof callback === 'function') {
      callback(usr, msg);
    }
  };
};

